import io.quarkus.arc.Arc;
import io.quarkus.config.ConfigVariable;
import io.quarkus.runner.QuarkusRunner;
import io.smallrye.common.thread.Threads;
import jakarta.json.JsonObject;
import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.ws.rs.client.Invocation;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.Response;
import org.apache.commons.lang3.time.FastDateFormat;
import org.glassfish.jersey.internal.Util;
import org.mockito.Mock;
import org.slf4j.Logger;
import org.slab.InterfaceTable;
import software.amazon.awssdk.annotations.SdkPublicApi;

import java.io.IOException;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import okhttp3.Request;
import okhttp3.Response as OkHttpResponse;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;

@ApplicationScoped
public class SandeshClient {
    private static final Logger LOGGER = Util.getLogger(SandeshClient.class);
    @ConfigVariable("sandesh.api.url")
    private String apiUrl;
    @Inject
    private InterfaceTable interfaceTableMock;
    private WebTarget target;
    private OkHttp3Client okHttp3Client;
    private final ObjectMapper mapper = new ObjectMapper();
    private AtomicLong totalRequests = new AtomicLong(0);
    private AtomicInteger successfulSessions = new AtomicInteger(0);
    private AtomicInteger failedSessions = new AtomicInteger(0);
    private AtomicLong lastFailureTime = Instant.now();

    public void initialize() {
        this.target = java.ws.rs.client.ClientBuilder.newClient().target(apiUrl);
        this.okHttp3Client = OkHttp3ClientProvider.get();
    }

    public void startPeriodicFetch() {
        Threads.startDaemonThread(() -> periodicFetchLoop());
    }

    private void periodicFetchLoop() {
        try {
            while (!Thread.currentThread().isInterrupted()) {
                sendRequest();
                TimeUnit.SECONDS.sleep(getRetryInterval());
            }
        } catch (Exception e) {
            LOGGER.error("Periodic fetch loop encountered an error: {}", e.getMessage(), e);
        }
    }

    private void sendRequest() {
        try {
            Response response = target.request().get(okHttp3Client).invoke();
            if (response.readEntity(JsonObject.class) != null) {
                processResponse(response);
            } else {
                failedSessions.incrementAndGet();
            }
        } catch (IOException e) {
            handleException(e);
        }
    }

    private void processResponse(Response response) {
        try {
            JsonObject json = response.readEntity(JsonObject.class);
            if (validateResponse(json)) {
                successfulSessions.incrementAndGet();
                // Process the validated JSON data here
            } else {
                failedSessions.incrementAndGet();
            }
        } catch (IOException e) {
            handleException(e);
        }
    }

    private boolean validateResponse(JsonObject json) {
        // Define your validation logic based on predefined schemas here
        return true;
    }

    private void handleException(Exception e) {
        if (System.currentTimeMillis() - lastFailureTime.toEpochMilli() > getRetryBackoff()) {
            failedSessions.incrementAndGet();
        }
        LOGGER.error("An error occurred while processing the request: {}", e.getMessage(), e);
    }

    private long getRetryInterval() {
        long retryInterval = 1000L; // initial retry interval in milliseconds
        long backoff = getBackoff();
        if (failedSessions.get() > 3) {
            retryInterval += backoff * Math.pow(2, failedSessions.get());
        }
        return retryInterval;
    }

    private long getRetryBackoff() {
        // Configure the backoff strategy here
        return 500L; // backoff in milliseconds
    }

    public void stop() {
        LOGGER.info("Shutting down SandeshClient...");
        okHttp3Client.shutdown();
        LOGGER.info("Total requests sent: {}", totalRequests);
        LOGGER.info("Successful proxy sessions processed: {}", successfulSessions);
        LOGGER.info("Failed proxy sessions encountered: {}", failedSessions);
    }
}
```

