      // Initialize component properties
      var resourceId, url;

      this.$onInit = function() {
        // Set initial component properties or handle errors
      };

      this.refreshFields = function() {
        if (ApiService.isBusy()) return; // Prevent concurrent requests
        ApiService.get(url, resourceId)
          .then(data => $scope.$apply(() => this.processData(data)))
          .catch(error => console.error('Error fetching data:', error));
      };

      this.processData = function(data) {
        // Process the retrieved data and update dialog fields
      };
    })
    .service('ApiService', function($q, $http) {
      var requests = [];

      this.get = function(url, id) {
        if (requests.some(request => request[0] === url && request[1] === id)) return $q.defer().promise; // Batch requests

        requests.push([url, id]);

        var deferred = $q.defer();

        $http.get(`${url}/${id}`)
          .then(response => {
            requests = requests.filter(request => request !== [url, id]); // Clear completed request
            deferred.resolve(response.data);
          })
          .catch(error => {
            console.error('Error fetching data:', error);
            requests = requests.filter(request => request !== [url, id]); // Clear failed request and notify users
            deferred.reject();
          });

        return deferred.promise;
      };

      this.isBusy = function() {
        return requests.length > 0;
      };
    });
</script>
