<script>
  angular.module('myApp')
    .service('TextAnalysisService', function() {
      this.countOldTestamentBooks = function(text) {
        var regex = /([A-Z][a-z]+|[A-Z])/g; // Match uppercase and lowercase book names with optional space between words
        var matches = text.match(regex);

        if (!matches) return 0;

        var counts = {};
        angular.forEach(matches, function(bookName) {
          bookName = bookName.toLowerCase();

          if (Object.prototype.hasOwnProperty.call(counts, bookName)) {
            counts[bookName]++;
          } else {
            counts[bookName] = 1;
          }
        });

        return Object.keys(counts).reduce((sum, bookName) => sum + counts[bookName], 0);
      };
    });
