let cache = new Map();

function copyBufferedData(dataChunks, byteCount) {
  const resultBuffer = Buffer.allocUnsafe(byteCount);
  let offset = 0;

  for (const chunk of dataChunks) {
    if (offset + chunk.length > byteCount) throw new Error('Byte count exceeded');

    resultBuffer.copy(chunk, offset, 0, chunk.length);
    offset += chunk.length;
  }

  return resultBuffer;
}

