fn compile_rust_project(path: &str) -> Result<(i32, usize)> {
    let start = Instant::now();
    let mut memory_usage = 0;

    // Fetch and load resource bundle
    let bundle_path = tempfile::NamedTempFile::new().map_err(|e| e.into())?;
    let bundle_content = fetch_bundle(bundle_path.path()).map_err(|e| e.into())?;
    let bundle: ResourceBundle = from_str(&bundle_content).map_err(|e| e.into())?;

    // Install custom logging hook if necessary
    // ...

    // Compile Rust project concurrently with resource management and potential race condition handling
    let mut exit_codes = Vec::new();
    for item in bundle {
        let item_path = Path::new(path).join(&item);
        let output = Command::new("rustc")
            .args(&["-o", &item_path.with_extension("out"), &item])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|e| e.into())?;

        // Measure compilation time and memory usage for each item concurrently
        let mem_start = mem::maybe_allocate(1, false);
        exit_codes.push(output.wait().map_err(|e| e.into())?.code().unwrap());
        let mem_end = mem::maybe_dealloc(mem_start, false);
        memory_usage += mem_end - mem_start;
    }

    // Ensure efficient resource management and handle potential race conditions
    // ...

    info!("Compilation took {:?}", start.elapsed());
    info!("Memory usage is {}", memory_usage);

    if exit_codes.iter().any(|code| *code != 0) {
        return Err("One or more compilation failed".into());
    }

    Ok((exit_codes.len(), bundle.len()))
}

