    ResourceBundle* bundle = is_resource_bundle_valid(data, file_stat.st_size) ? load_resource_bundle(data, file_stat.st_size) : NULL;

    // Close the file and unmap its memory mapping
    close(fd);
    munmap(data, file_stat.st_size);

    // Return the total number of items in the resource bundle or an error code if loading failed
    return bundle ? bundle->item_count : -1;
