// Global variables and mutex for thread safety
char g_max_filename_length = 256;
pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
char g_deployment_environment[32] = "default"; // Customizable for different environments

/**
 * Generates a unique filename using timestamp, UUID, and version identifier.
 * @param original_filename Original filename to generate a new one from.
 * @param deployment_env Environment-specific naming conventions.
 * @return Unique filename or NULL on error.
 */
char* generate_unique_filename(const char* original_filename, const char* deployment_env) {
    // Lock mutex to ensure thread safety
    pthread_mutex_lock(&g_mutex);

    // Combine deployment environment and original filename
    size_t len = strlen(deployment_env) + strlen(original_filename) + g_max_filename_length;

    char* unique_filename = malloc(len + 1);
    if (!unique_filename) {
        pthread_mutex_unlock(&g_mutex);
        return NULL;
    }

    snprintf(unique_filename, len + 1, "%s%s", deployment_env, original_filename);

    // Append timestamp and UUID to the filename
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];
    char uuid_str[37];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y%m%d_%H%M%S", timeinfo);

    UUID uuid;
    uuid_generate(uuid);
    snprintf(uuid_str, sizeof(uuid_str), "%08x-%04x-%04x-%04x-%08x%04x",
        uuid[0], uuid[1], uuid[2], uuid[3],
        uuid[4], uuid[5]);

    len = strlen(unique_filename) + strlen(time_str) + strlen(uuid_str) + 1; // For the period (.) separator

    unique_filename = realloc(unique_filename, len + 1);
    if (!unique_filename) {
        free(unique_filename);
        pthread_mutex_unlock(&g_mutex);
        return NULL;
    }

    strcpy(unique_filename + strlen(unique_filename), time_str);
    strcpy(unique_filename + strlen(unique_filename) - strlen(uuid_str), ".");
    strcpy(unique_filename + strlen(unique_filename) - strlen(uuid_str) - 1, uuid_str);

    // Update version identifier and log the event using the external configuration management system
    int version = get_version(); // Replace with your implementation for getting the current version
    update_version(version + 1);
    log_event("Filename generation", unique_filename);

    pthread_mutex_unlock(&g_mutex);
    return unique_filename;
}

/**
 * Main function to demonstrate usage of generate_unique_filename.
 */
int main() {
    const char* original_filename = "example.txt";
    const char* deployment_env = "production";
    char* unique_filename = generate_unique_filename(original_filename, deployment_env);

    if (!unique_filename) {
        fprintf(stderr, "Failed to generate unique filename\n");
        return 1;
    }

    printf("Generated unique filename: %s\n", unique_filename);

    free(unique_filename);
    return 0;
}
```

