            {
                ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;

                var credentials = await _authService.AuthenticateAsync();
                if (credentials == null) return null;

                httpClient.DefaultRequestHeaders.Add("Authorization", "Bearer " + credentials.Token);

                using (var response = await httpClient.GetAsync("https://remote-server.com/api/data"))
                {
                    if (!response.IsSuccessStatusCode) return null;

                    var encryptedData = await response.Content.ReadAsByteArrayAsync();
                    var data = JsonConvert.DeserializeObject<EncryptedData>(Encoding.UTF8.GetString(encryptedData));

