    stream.pipe(gzip).on('data', async (chunk) => {
      if (!uploadId) {
        uploadId = await cloudStorageService.initiateUpload(req.body.bucketName, req.body.folderName); // Handle intermittent connectivity
      }
      await cloudStorageService.uploadChunk(uploadId, chunk, chunkIndex++);
