#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = Config::load()?;
    let logger = Logger::new();

    // Initialize rate limiter and error handler
    let rate_limiter = RateLimiter::new(config.rate_limit);
    let error_handler = ErrorHandler::new(logger.clone());

    // Create API clients for each supported format (JSON, XML)
    let json_client = ApiClient::new(ApiEndpoint::Json, config.api_url, config.api_token, rate_limiter.clone(), error_handler.clone())?;
    let xml_client = ApiClient::new(ApiEndpoint::Xml, config.api_url, config.api_token, rate_limiter.clone(), error_handler.clone())?;

    // Initialize data processor and start asynchronous tasks
    let data_processor = DataProcessor::new(json_client, xml_client, logger.clone());
    let runtime = Runtime::new().unwrap();
    let app = Arc::new(App::new(data_processor, rate_limiter, error_handler, logger));

    // Run the application until an interrupt signal is received
    let handle = app.spawn();
    let ctrler = interrupt::control_handle().expect("Failed to create a control handle");
    runtime.block_on(async move {
        if ctrler.poll().await?.is_ok() {
            runtime.shutdown_on_new_task();
            log::info!("Shutting down gracefully...");
        }
        handle.await??;
    })?;

    Ok(())
}
