#include "LoggingFramework.h" // Handles logging
#include "MessageBroker.h" // Sends event notifications

class ConditionalInsertionService {
public:
    void insertAfterIfCondition(std::forward_list<std::string>& logEntries,
                                std::function<bool(const std::string&)> predicate,
                                const std::string& target,
                                const std::string& value) {
        // Default settings if configuration service is down
        static auto defaultPredicate = [](const std::string& entry) { return true; };
        static std::chrono::milliseconds defaultRetryInterval = std::chrono::milliseconds(100);
        static int maxRetries = 5;

        // Load configuration from external service if available
        auto configService = getConfigurationService();
        auto [predicateFunc, retryInterval, maxAttempts] = loadConfigIfAvailable(configService);
        if (!predicateFunc) {
            predicateFunc = defaultPredicate;
        }
        if (!retryInterval) {
            retryInterval = defaultRetryInterval;
        }
        if (!maxAttempts) {
            maxAttempts = maxRetries;
        }

        std::unique_ptr<IMessageBroker> messageBroker;
        try {
            messageBroker = getMessageBroker();
            sendEventNotification(messageBroker.get(), "InsertAfterIfConditionStarted");
        } catch (const std::exception& e) {
            LOG_ERROR("Failed to send event notification: {}", e.what());
        }

        // Implement exponential backoff and circuit-breaking logic
        int attempts = 0;
        auto lastErrorTime = std::chrono::steady_clock::now();
        while (attempts < maxAttempts) {
            if (predicateFunc(target)) {
                logEntries.insert_after(std::find_if(logEntries.cbegin(), logEntries.cend(), [&](const auto& entry) { return entry == target; }), value);
                break;
            }
            std::this_thread::sleep_for(retryInterval * std::pow(2, attempts));
            ++attempts;

            if (std::chrono::steady_clock::now() - lastErrorTime > std::chrono::seconds(1)) {
                LOG_WARNING("Configuration service unavailable for {} seconds, falling back to default settings", maxAttempts);
                predicateFunc = defaultPredicate;
            }
        }

        if (attempts == maxAttempts) {
            LOG_ERROR("Failed to insert log entry after condition");
        } else {
            sendEventNotification(messageBroker.get(), "InsertAfterIfConditionCompleted");
        }
    }

private:
