use std::process::{Command, Stdio};
use std::time::Instant;
use std::os::unix::prelude::ResourceId;
use sync_rs::SyncLazy;
use rustc_driver::{catch_with_exit_code, Driver};

fn measure_compilation(log_hook: &'static SyncLazy<Box<FnMut(&str) + 'static>) {
    let start = Instant::now();
    let mut cmd = Command::new("rustc");
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.arg("--crate-name").arg("my_project"); // Replace with your project name

    let output = match cmd.spawn() {
        Ok(process) => {
            process.stdout.as_mut().unwrap().write(log_hook.call(&format!("Starting compilation...")));
            let mut exit_code = catch_with_exit_code(process);
            let end = Instant::now();
            log_hook.call(&format!(
                "Compilation took {} seconds, RSS: {}",
                end.duration_since(start).as_secs_f64(),
                ResourceId::get()
            ));
            exit_code
        }
        Err(e) => {
            log_hook.call(&format!("Error during compilation: {}", e));
            std::process::ExitCode::FAILURE
        }
    };
}
```

