```java
import java.io.IOException;
import java.nio.channels.*;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.Map;

public class ConnectionManager {
    private final Selector selector;
    private final Map<Integer, SelectionKey> connections = new HashMap<>();

    public ConnectionManager(SelectorGroup group) throws IOException {
        this.selector = group.selectNow();
    }

    public void registerConnection(SelectionKey key) {
        try {
            connections.put(key.attachment(), key);
        } catch (ConcurrentModificationException e) {
            System.err.println("Concurrent modification exception while adding connection: " + e.getMessage());
        }
    }

    public void deregisterConnection(SelectionKey key) {
        connections.remove(key.attachment());
    }

    // Other methods for selecting, accepting and processing connections...
}
```

