6. DNS Resolution Function (in C)

```c
#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>

int get_ip(const char *hostname, u_char **ip_addr) {
    struct hostent *he = gethostbyname(hostname);
    if (!he) {
        perror("gethostbyname");
        return 1;
    }

    if (he->h_length != sizeof(struct in_addr)) {
        fprintf(stderr, "Invalid IP address length for host %s\n", hostname);
        return 1;
    }

    struct in_addr **addr_list = (struct in_addr **)he->h_addr_list;
    *ip_addr = malloc(sizeof(u_char) * INET_ADDRSTRLEN);

    if (!inet_ntop(AF_INET, &((*addr_list)[0]), *ip_addr, sizeof(*ip_addr))) {
        perror("inet_ntop");
        free(*ip_addr);
        return 1;
    }

    return 0;
}
```

This function uses the standard library's gethostbyname and inet_ntop functions to perform DNS resolution for a given hostname, handling errors gracefully. The function also limits the capabilities of the process by only allowing it to resolve IP addresses for valid hostnames.']

