            {
                _logger.LogError("Specified directory does not exist.");
                throw new DirectoryNotFoundException($"The directory '{directoryPath}' was not found.");
            }

            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                _logger.LogError("Directory contains no valid web.config file.");
                throw new FileNotFoundException($"The file '{webConfigPath}' was not found.");
