                    if (environmentConfig != null && environmentConfig.Any())
                    {
                        var queryParameters = string.Join("&", environmentConfig.Select(kvp => $"{kvp.Key}={kvp.Value}"));
                        request.Headers.Add("X-Environment", queryParameters);
                    }

                    await request.SendAsync(connection.RequestStream, HttpCompletionOption.ResponseHeadersRead, CancellationToken.None);
                }
            }

