const queue = require('./queue');

const controller = express.Router();

controller.use(bodyParser.json());
controller.options('*', cors());

controller.post('/command', auth, async (req, res) => {
  try {
    const command = sanitizer.validate(req.body, sanitizer.commandSchema);
    await queue.enqueue(command);
    return res.send({ success: true });
  } catch (error) {
    console.error(error);
    return res.status(500).send({ error: 'Internal Server Error' });
  }
});

controller.get('/command/:id', auth, async (req, res) => {
  try {
    const commandStatus = await queue.getStatus(req.params.id);
    return res.send({ status: commandStatus });
  } catch (error) {
    console.error(error);
    return res.status(500).send({ error: 'Internal Server Error' });
  }
});

module.exports = controller;
```

