```csharp
using System;
using System.Collections.Generic;
using System.Net.Http;
using Newtonsoft.Json;
using MathNet.Numerics.Distributions;
using System.Threading.Tasks;
using System.Diagnostics;

public class RandomValueGenerator
{
    private readonly Normal _gaussianDist;
    private readonly Uniform _uniformDist;
    private string _configurationUrl;
    private Dictionary<string, object> _configSettings;

    public RandomValueGenerator(Dictionary<string, object> config)
    {
        _configSettings = config;
        Initialize();
    }

    public RandomValueGenerator(string configurationUrl)
    {
        _configurationUrl = configurationUrl;
        LoadConfiguration().Wait();
        Initialize();
    }

    private async Task Initialize()
    {
        if (_configurationUrl != null)
            await LoadConfiguration();

        if (_configSettings == null || !_configSettings.ContainsKey("distribution") || _configSettings["distribution"] is not string distribution)
            throw new ArgumentException("Invalid configuration for RandomValueGenerator.");

        switch (distribution.ToLower())
        {
            case "uniform":
                _uniformDist = new Uniform(GetDouble(_configSettings, "min"), GetDouble(_configSettings, "max"));
                break;
            case "gaussian":
                double mean = GetDouble(_configSettings, "mean");
                double stdDeviation = GetDouble(_configSettings, "standard_deviation");
                _gaussianDist = new Normal(mean, stdDeviation);
                break;
            default:
                throw new ArgumentException("Invalid distribution type specified.");
        }
    }

    private async Task LoadConfiguration()
    {
        try
        {
            using HttpClient httpClient = new HttpClient();
            string jsonConfig = await httpClient.GetStringAsync(_configurationUrl);
            _configSettings = JsonConvert.DeserializeObject<Dictionary<string, object>>(jsonConfig);
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Error loading configuration: {ex}");
            _configSettings = new Dictionary<string, object>(); // Provide a default set of config values if configuration fetch fails
        }
    }

    private T GetValue<T>(Dictionary<string, object> dict, string key)
    {
        if (!dict.ContainsKey(key))
            throw new KeyNotFoundException($"Key '{key}' not found in dictionary.");

        return (T)Convert.ChangeType(dict[key], typeof(T));
    }

    public double NextGaussian() => _gaussianDist.Sample();
    public double NextUniform() => _uniformDist.Sample();
    public int NextInt(int maxValue) => (int)(NextUniform() * maxValue); // Assumes the range is 0 to maxValue
}
```

