using StackExchange.Redis;

public class DynamicRandomValueGenerator
{
    private readonly IDatabase _redisDatabase;
    private readonly IRestClient _restClient;
    private readonly ILogger _logger;
    private readonly MessageQueueProducer _messageQueueProducer;

    public enum DistributionType { Uniform, Gaussian, Exponential }

    private Dictionary<DistributionType, Func<Random, double>> distributionFunctions;
    private Configuration configuration;

    public DynamicRandomValueGenerator(IDatabase redisDatabase, IRestClient restClient, ILogger logger, MessageQueueProducer messageQueueProducer)
    {
        _redisDatabase = redisDatabase;
        _restClient = restClient;
        _logger = logger;
        _messageQueueProducer = messageQueueProducer;

        distributionFunctions = new Dictionary<DistributionType, Func<Random>>
        {
            [DistributionType.Uniform] = GenerateUniform,
            [DistributionType.Gaussian] = GenerateGaussian,
            [DistributionType.Exponential] = GenerateExponential
        };
    }

    private void InitializeConfiguration()
    {
        var configurationSources = new List<Func<JObject>> { GetConfigFromApi, GetConfigFromYaml, GetConfigFromRedis };

        // Use first available configuration source
        foreach (var configSource in configurationSources)
        {
            if (configSource() != null)
            {
                LoadConfiguration(configSource());
                return;
            }
        }

        _logger.LogError("Could not fetch initial configuration settings.");
    }

    private void LoadConfiguration(JObject config)
    {
        configuration = new Configuration(config);
        _redisDatabase.HashTagValueAdded += (_, tag, value) =>
        {
            if (tag == configuration.RedisCacheKey)
            {
                InitializeConfiguration();
            }
        };
    }

    private async Task GenerateAndLogAsync(DistributionType distributionType, int count, string logMessage)
    {
        var random = new Random();

        try
        {
            for (int i = 0; i < count; i++)
            {
                double value = distributionFunctions[distributionType](random);
                _logger.LogInfo(logMessage + $": {value}");
                await Task.Delay(TimeSpan.FromMilliseconds(configuration.LoggingInterval));
            }
        }
        catch (Exception ex)
        {
            ExceptionDispatchInfo.Capture(ex).Throw();
        }
    }

    public async Task GenerateRandomValuesAsync()
    {
        await GenerateAndLogAsync(DistributionType.Uniform, configuration.UniformCount, "uniform");
        await GenerateAndLogAsync(DistributionType.Gaussian, configuration.GaussianCount, "gaussian");
        await GenerateAndLogAsync(DistributionType.Exponential, configuration.ExponentialCount, "exponential");
    }

    private double GenerateUniform(Random random) => random.NextDouble();
    private double GenerateGaussian(Random random) => Math.Sqrt(-2.0 * Math.Log(random.NextDouble())) * configuration.GaussianStdDev * configuration.GaussianMean;
    private double GenerateExponential(Random random) => -Math.Log(1.0 - random.NextDouble()) / configuration.ExponentialLambda;

    // ... Other helper methods for config retrieval, error handling, and analytics
}

public class Configuration
{
    public string ApiEndpoint { get; set; }
    public string YamlFilePath { get; set; }
    public RedisCacheOptions RedisCacheOptions { get; set; }

