    public int UniformCount { get; set; }
    public double GaussianMean { get; set; }
    public double GaussianStdDev { get; set; }
    public double ExponentialLambda { get; set; }

    // ... Other configuration properties

    public string RedisCacheKey => $"dynamic_random_value_generator:{GetHashCode()}";

    public Configuration(JObject config)
    {
