```javascript
const { exec } = require('child_process');

function safeExec(command, callback, env) {
  const options = {
    maxBuffer: 1024 * 1024, // Set maximum buffer size for command output
    shell: true, // Use the system shell to execute command
  };

  exec(command, options, (error, stdout, stderr) => {
    if (error) {
      console.error(`exec error: ${error}`);
      return;
    }

    callback(stdout, stderr);
  });

  // Pass environment variables to the subprocess by merging with process.env
  const mergedEnv = Object.assign({}, process.env, env);
}
