    {
        private readonly IConfiguration _configuration;
        private readonly ConnectionMultiplexer _redis;
        private readonly IBackgroundJobClient _backgroundJobClient;

        public ContentController(IConfiguration configuration)
        {
            _configuration = configuration;
            _redis = ConnectionMultiplexer.Connect(_configuration["Redis:ConnectionString"]);
            _backgroundJobClient = new BackgroundJobClient(_redis);
        }

        [HttpPost]
        public IActionResult UpdateContent([FromBody] ContentRequest request)
        {
            if (!IsValidInput(request)) return BadRequest();

            var cacheEntryName = "content";
            var redisCacheClient = _redis.GetDatabase();

            // Check if cached content exists, if so read from cache
            if (redisCacheClient.KeyExists(cacheEntryName))
            {
                var cachedContent = redisCacheClient.StringGet(cacheEntryName);
                return Ok(cachedContent);
            }

            // If not in cache, process request and update content
            UpdateAndStoreContent(request).ContinueWith(task =>
            {
                if (task.IsFaulted)
                {
                    HandleException(task.Exception);
                }
                else
                {
                    var updatedContent = task.Result;

                    redisCacheClient.StringSet(cacheEntryName, updatedContent, TimeSpan.FromMinutes(10));
                    PublishToCDN(updatedContent);
                }
            });

            return Accepted();
        }

