    public interface ILoggingService
    {
        void Log(string message);
    }

    public class EndpointController : Controller
    {
        private readonly ICacheService _cacheService;
        private readonly ILoggingService _loggingService;
        private const int MaxContentSize = 1024 * 1024 * 5; // 5MB limit
        private const string ContentTypeRegex = @"^text/html|application/xml|application/xhtml\+xml$";

        public EndpointController(ICacheService cacheService, ILoggingService loggingService)
        {
            _cacheService = cacheService;
            _loggingService = loggingService;
        }

        [HttpPut("{element}")]
        public async Task<IActionResult> UpdateElementAsync(string element, [FromBody] string content)
        {
            if (!Regex.IsMatch(Request.ContentType, ContentTypeRegex))
                return BadRequest("Invalid content type.");

            if (content.Length > MaxContentSize)
                return BadRequest($"Content size exceeds the limit of {MaxContentSize} bytes.");

            try
            {
                await ValidateAndSanitizeHTMLAsync(content);

                var cachedContent = await _cacheService.GetOrCreateAsync($"element-{element}", async () => await GetElementContentAsync(element));

                string updatedContent = HttpUtility.HtmlEncode(content) + cachedContent;
                var updatedCacheEntry = new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromMinutes(5));
                await _cacheService.SetAsync($"element-{element}", updatedContent, updatedCacheEntry);

                return Ok();
            }
            catch (Exception ex)
            {
                _loggingService.Log($"Failed to update element '{element}': {ex.Message}");
                return StatusCode((int)HttpStatusCode.InternalServerError);
            }
        }

