    // Generate the footer section, including all valid scripts
    for (const script of validScriptVersions) {
      const scriptElement = document.createElement('script');
      scriptElement.id = script.split('/').pop();
      scriptElement.innerHTML = script;
      footer.appendChild(scriptElement);
    }

    return footer;
  }

  async function appendFooter() {
    try {
      const validScriptVersions = await Promise.all([fetchScriptVersions(scriptArray.map(s => s.id)), validateScriptVersions]);
      const footer = buildFooter(validScriptVersions[1]);

      // Append the footer to the document efficiently using nextTick or requestAnimationFrame
