        for (int i = 0; i < size; ++i) {
            auto record = std::make_unique<Record>();
            record->value = min + (rand() % (max - min + 1));
            records[std::to_string(next_id++)] = std::move(record);
        }
        kvs_api = [kvs_impl](const Record& record) { /* Implement the API call using the provided KVS implementation */ };
    }

    // Thread-safe function to add a new record or update an existing one
    void insertOrUpdate(const std::string& metadata, const std::vector<std::string>& tags, int value) {
        Record* record = nullptr;
        auto it = records.find(std::to_string(value));
        if (it != records.end()) {
            record = it->second.get();
        } else {
            // Use the memory pool for allocation, if available
            void* data = mem_pool.allocate(sizeof(Record));
            if (!data) {
                throw std::runtime_error("Memory allocation failed");
            }
            new (data) Record();
            record = static_cast<Record*>(data);
        }

        // Fill the record data and insert it into the hash table, updating the value if needed
        record->value = value;
        record->metadata = metadata;
        record->tags = tags;
        records[std::to_string(record->value)] = std::unique_ptr<Record>(record);
    }

    // Batch persistence mechanism
