```java
public abstract class ApiGateway implements ServletContextListener {
    protected final ServiceRegistry serviceRegistry;
    protected final List<RequestInterceptor> requestInterceptors;
    protected final Cache cache;
    // ...

    public ApiGateway(ServiceRegistry serviceRegistry, List<RequestInterceptor> requestInterceptors) {
        this.serviceRegistry = serviceRegistry;
        this.requestInterceptors = requestInterceptors;
        this.cache = new Cache();
    }

    protected abstract RouteRule getRouteRule();

    @Override
    public void contextInitialized(ServletContextEvent sce) {
        // Initialize components and load dynamic configuration...
    }

    @Override
    public void contextDestroyed(ServletContextEvent sce) {
        // Gracefully shutdown components...
    }

    protected Response routeAndCache(Request request) {
        Service service = getRouteRule().selectService(serviceRegistry.getServiceId(request), request.getHeaders(), request.getQueryParameters());
        return callAndCache(service, request);
    }

    private Response callAndCache(Service service, Request request) {
        Response response = service.call(request);
        cache.putIfAbsent(key, response);
        return response;
    }
}
