import time

def retry(func, max_attempts=5, delay_factor=1.5, jitter=0.2):
    attempts = 0
    while attempts < max_attempts:
        try:
            return func()
        except Exception as e:
            attempts += 1
            time.sleep(delay_factor**attempts * (random.uniform(1-jitter, 1+jitter)))
    raise Exception("Maximum retries exceeded")
