2. C Program (Named: LineCounter):

```c
#include <stdio.h>
#include <stdlib.h>
#include <getopt.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>

int main(int argc, char **argv) {
    int c;
    int manpage = 0;
    const char *input_file = NULL;
    const char *output_file = NULL;

    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'h'},
        {"input", required_argument, 0, 'c'},
        {"output", optional_argument, 0, 'o'},
        {0}
    };

    while ((c = getopt_long(argc, argv, "h:c::o:", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                manpage = 1;
                break;
            case 'c':
                input_file = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-h] -c <input_file> [--output=<output_file>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (!input_file) {
        if (manpage) {
            printf("LineCounter - count lines in input file\n");
            printf("-c, --input           Specify the input file\n");
            printf("-o, --output          Output file [optional]\n");
            return EXIT_SUCCESS;
        }
        fprintf(stderr, "Error: No input file provided.\n");
        return EXIT_FAILURE;
    }

    int fd = open(input_file, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return EXIT_FAILURE;
    }

    int lines = 0;
    char buf[4096];
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buf, sizeof(buf))) > 0) {
        for (ssize_t i = 0; i < bytes_read; ++i) {
            if (buf[i] == '\n')
                ++lines;
        }
    }
    close(fd);

    if (output_file) {
        FILE *out = fopen(output_file, "w");
        if (!out) {
            perror("fopen");
            return EXIT_FAILURE;
        }
        fprintf(out, "%d\n", lines);
        fclose(out);
    } else {
        printf("%d\n", lines);
    }
    return EXIT_SUCCESS;
}
```']

