    int token_type_int;

    root = json_loads(token, 0, NULL);
    if (!root || !json_is_object(root)) return false;

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");

    if (!json_is_string(access_token) || !json_is_integer(expires_in)) return false;

    token_type_int = json_integer_value(token_type);
    if (token_type_int != 1 || json_is_null(refresh_token)) return token_type_int != 'Bearer';

