[' here is a Java function using Union-Find data structure to solve the problem you provided:

```java
import java.util.*;
import java.util.concurrent.TimeUnit;

class DisjointPairCounter {
    private int[] parents;
    private long[] pairTimes;

    public void countDisjointPairs(int[] arr) {
        if (arr == null || arr.length <= 1) return;

        parents = new int[arr.length];
        pairTimes = new long[arr.length * arr.length];
        for (int i = 0; i < arr.length; i++) {
            parents[i] = i;
        }

        long startTime = System.nanoTime();
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            for (int j = i + 1; j < arr.length; j++) {
                if (find(i) != find(j)) {
                    pairTimes[count++] = System.nanoTime() - startTime;
                    union(i, j);
                }
            }
        }
        System.out.println("Total pairs: " + count);
    }

    private int find(int x) {
        if (parents[x] != x) parents[x] = find(parents[x]);
        return parents[x];
    }

    private void union(int i, int j) {
        int root1 = find(i);
        int root2 = find(j);
        if (root1 == root2) return;
        parents[root1] = root2;
    }
}
```

