2. C function using fork and wait:

```c
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdlib.h>

int run_command_in_background(char* command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork failed");
        return 0;
    } else if (pid == 0) { // Child process
        execlp(command, command, NULL);
        perror("execlp failed");
        exit(1);
    }

    int status;
    waitpid(pid, &status, WNOHANG); // Parent process
    return WIFEXITED(status) ? WEXITSTATUS(status) == 0 ? 1 : 0 : -1;
}
```

