char *generateSecureFileName(char *filename, char *targetDir, const char *fileType, int numDigits) {
    pthread_mutex_lock(&lock);

    if (!isLoggerAvailable) {
        // Implement fallback logging mechanism
        logError("[ERROR] Logger service unavailable. Using local logs.");
    }

    // Validate directory and file type
    if (validatePath(targetDir)) {
        logError("[ERROR] Invalid target directory.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (!validateFileType(fileType)) {
        logError("[ERROR] Invalid file type.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Generate secure filename using UUID and timestamp
    char timestring[24];
    strftime(timestring, sizeof(timestring), "%Y%m%d-%H%M%S", localtime(&time(NULL)));
    char *filenameExtension = malloc(numDigits);
    for (int i = 0; i < numDigits; ++i) {
        sprintf(filenameExtension + i, "%d", rand() % 10);
    }

    // Incorporate random digits into the file extension
    char *extension = strchr(fileType, '.');
    if (extension != NULL) {
        memmove(extension + numDigits, extension + strlen(extension), strlen(extension) - (extension - fileType));
    } else {
        sprintf(fileType + strlen(fileType), ".%s", filenameExtension);
    }

    // Check for existing files with similar names and append a numeric suffix to ensure uniqueness
    char fullPath[1024];
    snprintf(fullPath, sizeof(fullPath), "%s/%s", targetDir, timestring + strlen(timestring) - 8);
    strcat(fullPath, fileType);
    int suffix = 1;
    while (access(fullPath, F_OK) == 0) {
        snprintf(fullPath + strlen(fullPath), sizeof(fullPath) - strlen(fullPath), "-%d", suffix++);
    }

    // Cleanup and return the generated filename
    free(filenameExtension);
    pthread_mutex_unlock(&lock);
    return strdup(fullPath);
}

// Validate path against whitelist
bool validatePath(char *path) {
    bool isValid = true;
    for (size_t i = 0, j = 0; i < strlen(path) && j < strlen(allowedChars); ++i, ++j) {
        if (path[i] == '/' || strchr(allowedChars, path[i]) == NULL) {
            isValid = false;
            break;
        }
    }

    // Validate directory paths up to 1024 characters
    if (strlen(path) > 1024) {
        isValid = false;
    }

    return isValid;
}

// Validate file type against whitelist
bool validateFileType(const char *fileType) {
    for (int i = 0; i < numFileTypes; ++i) {
        if (strcmp(fileType, fileTypes[i]) == 0) {
            return true;
        }
    }

    return false;
}
```

