['```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include "logging_framework.h" // Custom logging framework header

// Maximum number of threads to use for concurrent execution
#define MAX_THREADS 8

typedef struct {
    char *filename;
    size_t num_digits;
} filename_params;

void modify_extension(filename_params *params, semaphore_t *semaphore) {
    // Extract extension and calculate digit count
    const size_t file_len = strlen(params->filename);
    const char *dot = strchr(params->filename, '.');
    bool has_extension = dot != NULL;
    size_t num_digits = 0;
    if (!has_extension) {
        for (size_t i = 0; i < file_len; ++i) {
            if (isdigit(params->filename[i])) {
                ++num_digits;
            }
        }
    } else {
        const size_t ext_len = strlen(dot + 1);
        for (size_t i = 0; i < ext_len; ++i) {
            if (isdigit(dot[i])) {
                ++num_digits;
            }
        }
    }

    // Append digit count and file type to the extension
    char *modified_ext = malloc(strlen(dot + 1) + sizeof(char) * num_digits + sizeof(".txt") - 1);
    if (modified_ext == NULL) {
        log_error("Out of memory while modifying filename.");
        return;
    }

    snprintf(modified_ext, strlen(dot + 1) + sizeof(char) * num_digits + sizeof(".txt") - 1, "%.*s%*d.txt", ext_len, dot, num_digits, num_digits);

    // Replace the original extension with the new one and log the modification
    char modified_filename[file_len + strlen(modified_ext)];
    strncpy(modified_filename, params->filename, file_len - (has_extension ? strlen(dot) : 0));
    strcat(modified_filename, modified_ext);
    log_info("Modified filename: %s", modified_filename);

    // Free memory and return the modified filename
    free(params->filename);
    params->filename = modified_filename;
}

char* modifyFileName(const char *filename) {
    // Check for invalid filenames
    const size_t file_len = strlen(filename);
    if (file_len == 0 || strchr(filename, '/') != NULL || strchr(filename, ':') != NULL || strchr(filename, '<') != NULL || strchr(filename, '>') != NULL) {
        log_error("Invalid filename provided.");
        return NULL;
    }

    // Create parameters struct and initialize semaphore for thread-safe execution
    filename_params params = { .filename = (char *) malloc(file_len + 1), .num_digits = 0 };
    strcpy(params.filename, filename);
    semaphore_t semaphore;
    init_semaphore(&semaphore, MAX_THREADS);

    // Execute the modification in a concurrent manner with multiple threads
    pthread_t threads[MAX_THREADS];
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        params.num_digits = 0;
        modify_extension(&params, &semaphore);
        pthread_create(&threads[i], NULL, modifyFileNameHelper, &params);
    }

    // Wait for all threads to complete and join them
    for (size_t i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore(&semaphore);
    free(params.filename);
    return params.filename;
}
```

