2. Python Deserialization Function:

```python
import pickle
import sys
from abc import ABC, abstractmethod

class Serializable(ABC):
    @abstractmethod
    def serialize(self):
        pass

    @abstractmethod
    def deserialize(cls, data):
        pass

def deserialize_object(data: bytes) -> Serializable:
    try:
        obj = pickle.loads(data)
    except (TypeError, ValueError) as e:
        raise ValueError("Deserialization failed: {}".format(e))

    if not hasattr(obj, '__class__'):
        raise ValueError("Object class is not found.")

    return obj.__class__.deserialize(obj)
```']

