import java.math.BigDecimal;

public class PaymentProcessor {
    private Map<String, PaymentGateway> gateways;
    private ExternalCurrencyAPI currencyAPI;
    private Logger logger;

    public PaymentProcessor(Map<String, PaymentGateway> gateways, ExternalCurrencyAPI currencyAPI, Logger logger) {
        this.gateways = gateways;
        this.currencyAPI = currencyAPI;
        this.logger = logger;
    }

    public String generateSecureToken(int length) {
        StringBuilder token = new StringBuilder();
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(Instant.now().toString().getBytes());
            byte[] digest = md.digest();
            for (byte b : digest) {
                token.append(String.format("%02x", b));
            }
            if (token.length() > length) token = token.substring(0, length);
        } catch (Exception e) {
            logger.error("Error generating secure token: " + e.getMessage());
        }
        return token.toString();
    }

    public void processTransaction(String token, BigDecimal amount, String currency, TransactionType type) {
        // Switch gateways based on configuration, transaction type, and availability
        PaymentGateway gateway = chooseGateway();

        try {
            // Real-time currency conversion
            BigDecimal convertedAmount = convertCurrency(amount, currency);

            // Integrate with the chosen payment gateway
            GatewayResponse response = gateway.processPayment(convertedAmount, token);

            if (response.isSuccess()) {
                // Log successful transaction
                logger.info("Transaction processed successfully: " + token);
            } else {
                // Handle errors and network timeouts gracefully
                handleError(token, response);
            }
        } catch (Exception e) {
