#include <stdbool.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct FsaState {
    char* name;
    size_t ref_count;
    struct FsaState* next;
} FsaState;

typedef struct FsaTransition {
