2. C Function for Running Command in Background:

```c
#include <stdio.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/wait.h>

int run_command(char *cmd) {
    pid_t pid = fork();

    if (pid == -1) {
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(cmd, cmd, NULL);
        _exit(127);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) ? WEXITSTATUS(status) : 0;
    }
}
```

