using namespace std;
using boost::asio::ip::tcp;

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rtxInfoTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
};

void populateNFAPICRCIndication(vector<NFAPI_CRC_INDICATION_PDU_T>& data, size_t N) {
    rand_t seed = time(nullptr);
    mt19937 engine(seed);
    uniform_int_distribution<> distRxInfoTag(0, 255), distRNTI(1, 65535), distCRCFlag(0, 1);

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdus;
        pdus.rtxInfoTag.tag = distRxInfoTag(engine);
        pdus.rnti.rnti = distRNTI(engine);
        pdus.crcIndicationTag.crcFlag = distCRCFlag(engine);
        data.push_back(pdus);
    }
}
