namespace DynamicRandomValueGenerator
{
    public interface IRandomStrategy
    {
        float NextFloat(float min, float max);
        int NextInt(int min, int max);
    }

    public abstract class RandomStrategy : IRandomStrategy
    {
        protected readonly Random _random;

        protected RandomStrategy() => _random = new Random();

        public virtual float NextFloat(float min, float max) => _random.NextFloat(min, max);
        public virtual int NextInt(int min, int max) => _random.Next(min, max);
    }

    public sealed class PseudoRandomStrategy : RandomStrategy
    {
        public override float NextFloat(float min, float max) => _random.NextSingle(min, max);
        public override int NextInt(int min, int max) => _random.Next(min, max);
    }

    public sealed class ThreadSafeRandomStrategy : RandomStrategy
    {
        private readonly ConcurrentRandom _concurrentRandom;

        public ThreadSafeRandomStrategy()
        {
            _concurrentRandom = new ConcurrentRandom();
        }

        public override float NextFloat(float min, float max) => _concurrentRandom.NextSingle(min, max);
        public override int NextInt(int min, int max) => _concurrentRandom.Next(min, max);
    }

    public sealed class CustomRandomStrategy : IRandomStrategy
    {
        private readonly Func<float, float, float> _generateFloat;
        private readonly Func<int, int, int> _generateInt;

        public CustomRandomStrategy(Func<float, float, float> generateFloat, Func<int, int, int> generateInt)
        {
            _generateFloat = generateFloat;
            _generateInt = generateInt;
        }

        public float NextFloat(float min, float max) => _generateFloat(min, max);
        public int NextInt(int min, int max) => _generateInt(min, max);
    }

    public sealed class DynamicRandomValueGenerator
    {
        private readonly ConcurrentDictionary<string, IRandomStrategy> _randomStrategies;
        private readonly HttpClient _httpClient;
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxDegreeOfParallelism;

        public DynamicRandomValueGenerator(int maxDegreeOfParallelism)
        {
            _randomStrategies = new ConcurrentDictionary<string, IRandomStrategy>();
            _httpClient = new HttpClient();
            _semaphore = new SemaphoreSlim(maxDegreeOfParallelism);
            _maxDegreeOfParallelism = maxDegreeOfParallelism;
        }

        public async Task AddRandomStrategyAsync(string name, IRandomStrategy randomStrategy)
        {
            await _semaphore.WaitAsync();
            try
            {
                _randomStrategies[name] = randomStrategy;
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public async Task<IRandomStrategy> GetRandomStrategyAsync(string name)
        {
            await _semaphore.WaitAsync();
            try
            {
                return _randomStrategies.GetOrAdd(name, _ => LoadCustomRandomStrategy());
            }
            finally
            {
                _semaphore.Release();
            }
        }

        private IRandomStrategy LoadCustomRandomStrategy()
        {
            var customStrategy = JsonConvert.DeserializeObject<CustomRandomStrategy>(HttpClientExtensions.GetStringAsync(_httpClient, "https://your-service-url/random-strategy").Result);
            return customStrategy;
        }

        public float NextFloat(float min, float max)
        {
            var strategy = GetRandomStrategy("Default");
            return strategy.NextFloat(min, max);
        }

        public int NextInt(int min, int max)
        {
            var strategy = GetRandomStrategy("Default");
            return strategy.NextInt(min, max);
        }

