    private readonly IDictionary<string, Random> _randomGenerators;
    private readonly ILogger<DynamicRandomValueGenerator> _logger;
    private readonly IConnectionMultiplexer _redis;
    private const string ConfigCacheKey = "random_generator_config";
    private readonly IConfigurationProvider _configurationProvider;

    public DynamicRandomValueGenerator(ILogger<DynamicRandomValueGenerator> logger, IConnectionMultiplexer redis, IConfigurationProvider configurationProvider)
    {
        _logger = logger;
        _redis = redis;
        _configurationProvider = configurationProvider;
        LoadConfigurations();
    }

    private void LoadConfigurations()
    {
        var cacheEntryOptions = new CacheEntryOptions().Expire(TimeSpan.FromMinutes(5));
        _randomGenerators = _redis.GetDatabase().HashEntriesByHashNameAsync(ConfigCacheKey).Result.ToDictionary(entry => entry.Key, entry => new Random());

        FetchAndCacheConfigurations();
    }

    private async void FetchAndCacheConfigurations()
    {
        try
        {
            var apiUrl = _configurationProvider["RandomGeneratorApiUrl"];
            var apiResponse = await MakeRequestAsync(apiUrl);

            if (apiResponse.IsSuccessful)
            {
                var configJson = apiResponse.Content;
                var configurations = JsonConvert.DeserializeObject<Dictionary<string, Configuration>>(configJson);
                CacheConfigurations(configurations);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to fetch configurations from API.");
        }
    }

    private void CacheConfigurations(IDictionary<string, Configuration> configurations)
    {
        foreach (var configuration in configurations)
        {
            var key = $"generator_{configuration.Key}";
            _redis.GetDatabase().HashStoreAsync(key, new Dictionary<RedisKey, RedisValue> { { "distribution", configuration.Distribution }, { "params", JsonConvert.SerializeObject(configuration.Parameters) } });
        }
    }

    private async Task<IRestResponse> MakeRequestAsync(string url)
    {
        var client = new RestClient(url);
        return await client.ExecuteTaskAsync(new RestRequest(Method.GET));
    }

