app = FastAPI()

origins = [
    "http://example.com",
    "https://example.com"
]

app.add_middleware(
    CORSMiddleware,
    allow_origins=origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"]
)

redis_client = redis.StrictRedis(host="redis-host", port=6379, db=0)

class APIResponse(BaseModel):
    status: int
    data: Union[Dict, str]

def get_api_data(url: str, params: Dict = None) -> APIResponse:
    response = requests.get(url, params=params)
    if response.status_code != 200:
        return APIResponse(status=response.status_code, data=response.text)
    else:
        return APIResponse(status=response.status_code, data=response.json())

def set_cache(key: str, value: Union[Dict, str], expiry: int):
    redis_client.setex(key, expiry, value)

def get_cache(key: str) -> Union[Dict, str]:
    return redis_client.get(key)

@app.on_event("startup")
async def startup():
    print("Microservice started.")

@app.get("/cache/{key}")
async def get_cached_data(key: str):
    cached_data = get_cache(key)
    if cached_data:
        return JSONResponse(content=cached_data, status_code=200)
    api_response = get_api_data(f"https://external-api.com/{key}")
    if api_response.status == 200:
        set_cache(key, api_response.data, 3600)
        return JSONResponse(content=api_response.data, status_code=200)
    else:
        # Handle API failure and adapt cache invalidation policies accordingly
        pass

@app.get("/healthcheck")
async def healthcheck():
    try:
        response = get_api_data("https://external-api.com/healthcheck")
        if response.status == 200:
            return JSONResponse(content="OK", status_code=200)
        else:
            # Adapt cache invalidation policies based on health check results
            pass
    except Exception as e:
        print(f"Error checking healthcheck: {e}")
        return JSONResponse(content="ERROR", status_code=500)
