['1. Data Structure and Caching Policy:
```cpp
#include <unordered_map>
#include <list>
#include <boost/circular_buffer.hpp>

class CacheEntry {
public:
    std::shared_ptr<void> data; // Replace with your actual data type
    uint64_t lastAccessTime;
};

class LRUCache {
public:
    explicit LRUCache(size_t capacity) : _capacity(capacity), _lruBuffer(capacity) {}

    void insertOrUpdate(const std::string& key, const std::shared_ptr<void>& data) {
        auto it = _cache.find(key);
        if (it != _cache.end()) {
            // Update access time and move to LRU position
            it->second->lastAccessTime = clock();
            _lruBuffer.pop_back();
            _lruBuffer.push_front(it->first);
        } else {
            if (_cache.size() >= _capacity) {
                // Evict least recently used item
                _lruBuffer.pop_back();
                auto evictedKey = _lruBuffer.front();
                _cache.erase(evictedKey);
            }
            _cache[key] = std::make_shared<CacheEntry>();
            _cache[key]->data = data;
            _cache[key]->lastAccessTime = clock();
            _lruBuffer.push_front(key);
        }
    }

private:
    size_t _capacity;
    boost::circular_buffer<std::string> _lruBuffer; // Replace with your preferred LRU queue implementation
    std::unordered_map<std::string, std::shared_ptr<CacheEntry>> _cache;
};
