import json
from typing import Dict, Any, Type, Callable

class JsonObjectFactory:
    def __init__(self, factory_registry: Dict[str, Callable]):
        self._factory_registry = factory_registry

    def create(self, id: str) -> Any:
        if id not in self._factory_registry:
            raise ValueError("Invalid object ID")

        factory = self._factory_registry[id]
        obj = factory(self)
        return obj.create()

    class FactoryRegistry:
        def __init__(self):
            self._factories = {}

        def register(self, id: str, factory: Type) -> None:
            self._factories[id] = factory

        def get_factory(self, id: str) -> Type:
            return self._factories.get(id)

    class JsonObject:
        _registry = JsonObjectFactory.FactoryRegistry()

        @classmethod
        def register(cls, id: str, factory: Type):
            cls.JsonObject.FactoryRegistry().register(id, factory)

        def create(self) -> Any:
            raise NotImplementedError("Must be implemented by subclasses")

        @staticmethod
        def from_json(data: Dict[str, Any]) -> "JsonObject":
            obj = JsonObject._registry.get_factory(data["id"])()
            obj.from_json(data)
            return obj
