class UnionFind {
public:
    explicit UnionFind(size_t size) : parent_(size, -1), rank_(size, 0) {}

    int findSet(int x) {
        if (parent_[x] < 0)
            return x;
        return parent_[x] = findSet(parent_[x]);
    }

    void unionSet(int x, int y) {
        int xRoot = findSet(x);
        int yRoot = findSet(y);
        if (xRoot == yRoot)
            return;

        if (-rank_[xRoot] > -rank_[yRoot])
            swap(xRoot, yRoot);
        parent_[yRoot] = xRoot;
        rank_[xRoot] += rank_[yRoot];
    }

private:
    vector<int> parent_;
    vector<int> rank_;
};

