```cpp
#include <iostream>
#include <nlohmann/json.hpp>
#include <stdexcept>

bool validateToken(const std::string& json) {
    nlohmann::json token = nlohmann::json::parse(json);

    if (!token.is_object()) {
        throw std::invalid_argument("Invalid JSON input");
    }

    if (!(token["access_token"].is_string() &&
          token["expires_in"].get<int>() > 0 &&
          (token["token_type"] == "Bearer"))) {
        throw std::invalid_argument("Invalid token format");
    }

    token.remove("refresh_token"); // Optional field

    return true;
}
