1. Derive keys from passwords using PBKDF2 with SHA-256:

```rust
extern crate openssl;
use openssl::symm::KeyDerivFunc;
use openssl::pkcs5::{PKCS5, PKCS5_PassphraseDeriver};

fn derive_key(password: &str, salt: &[u8], iterations: u32) -> Vec<u8> {
    let pkcs5 = PKCS5::new(PKCS5_PassphraseDeriver::new(), salt.to_vec(), iterations)?;
    let key = pkcs5.derive_key(password.as_bytes())?;
    key.to_vec()
}
```

2. Implement 2FA using TOTP:

```rust
extern crate chrono;
use chrono::{TimeZone, Utc};
use openssl::hmac::{HMAC, NewMac};
use openssl::sha::Sha1;

fn calculate_otp(shared_secret: &[u8], counter: u32) -> String {
    let now = Utc::now().time().timestamp();
    let mut hmac = HMAC::new(NewMac::sha1(), shared_secret)?;
    let key = format!("{}:{}", now, counter);
    hmac.update(&key.as_bytes());
    let hash = hmac.finalize()?;
    let digest = hex::encode(hash);
    let otp = digest[6..10].parse::<u32>().unwrap();
    format!("{}", (otp % 100000) as u64)
}
```

