using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class DataDecryption
{
    public byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes gcm = AES.Create())
        {
            gcm.Key = key;
            gcm.IV = iv;
            GCMPaddingScheme scheme = new GCMPaddingScheme();
            byte[] plaintext = scheme.Decrypt(gcm, ciphertext, out _);
