std::unordered_map<NodeID, std::vector<NeighborID>> neighbors;
void gossip() {
    std::mt19937 rng(time(0));
    for (auto& [node, neighbors] : neighbors) {
        auto it = std::next(std::random_shuffle(neighbors.begin(), neighbors.end());
