- Exponential Backoff and Retry Logic:

```cpp
#include <chrono>

// ...
void callAPI(std::function<void()> apiCall) {
    const int maxRetries = 5;
    std::atomic_int retries{0};

    auto backoffDuration = std::chrono::milliseconds(100);
    for (int i = 0; i < maxRetries; ++i) {
        try {
            apiCall();
            break;
        } catch (const std::exception& e) {
            if (++retries >= maxRetries) {
                throw e;
            }
            this_thread::sleep_for(backoffDuration);
            backoffDuration *= 2;
        }
    }
}
