let scriptCache = new Map();

function loadAndExecute(filename, callback) {
    // Handle cases where the file is not available or cannot be executed
    if (!filename || !fs.existsSync(filename)) {
        return callback(new Error(`File "${filename}" not found`));
    }

    let cacheKey = path.relative(__dirname, filename);
    if (scriptCache.has(cacheKey)) {
        // Handle scenarios where files are loaded in a different order than expected
        const script = scriptCache.get(cacheKey);
        return callback(null, script);
    }

    fs.readFile(filename, 'utf8', (err, data) => {
        if (err) {
            return callback(err);
        }

        let script = new Function('return ' + data);
        scriptCache.set(cacheKey, script);
        callback(null, script);
    });
}
