2. Union-Find algorithm implementation:
```csharp
class DisjointSet {
    std::vector<int> parent;
    std::vector<int> rank;
public:
    DisjointSet(int size) : parent(size), rank(size, 1) {
        for (int i = 0; i < size; ++i) parent[i] = i;
    }
    int findSet(int x) {
        if (parent[x] != x) parent[x] = findSet(parent[x]);
        return parent[x];
    }
    void unionSet(int x, int y) {
        int xRoot = findSet(x);
        int yRoot = findSet(y);
        if (xRoot == yRoot) return;
        if (rank[xRoot] > rank[yRoot]) std::swap(xRoot, yRoot);
        parent[xRoot] = yRoot;
        rank[yRoot] += rank[xRoot];
    }
};
```

