        // Modify the filename and create a new FileProcessor instance based on the file format
        std::string modifiedFilename = modifyFileName(entry.path().filename().string(), "txt", 4);
        FileProcessor* processor = createFileProcessor(modifiedFilename);
        if (!processor) continue; // Handle invalid filenames gracefully

        processors.push_back(processor);
    }

    PdfMerger merger(MAX_PDF_SIZE);
    std::vector<std::future<void>> tasks;

    for (auto& processor : processors) {
        tasks.emplace_back(async(launch::async, [processor]() { return processor->process(processor->getFilename()); }));
    }

    // Wait for all tasks to complete and merge the processed files
