// C function for modifying file name
#[no_mangle]
pub extern "C" fn modifyFileName(filename: *const c_char) -> *mut c_char {
    let filename = CStr::from_ptr(filename);
    let ext = filename.extension().unwrap_or_else(|| CString::new("").unwrap());
    let digit_count = ext.to_strs()[0].chars().filter(|c| c.is_digit(10)).count();
    let new_ext = format!("{:0>{ext_len}d}.txt", digit_count, ext_len = ext.to_strs()[0].len());
    let mut new_filename = CString::new(filename.into_string().replace(&ext.to_strs()[0], &new_ext)).unwrap();
    // Use the existing logging framework to audit the filename modification
    log!("Modified file name: {}", new_filename.as_str());
    boxed_ptr_to_raw(Box::new(new_filename))
}
```

