}

void DynamicNetworkConnectionManager::startHealthMonitoring() {
    if (_isRunning && _healthMonitorThreadId == std::thread::id()) {
        _healthMonitorThreadId = std::this_thread::get_id();

        for (auto& monitoringClient : _monitoringClients) {
            auto monitorTask = std::async(std::launch::async, [this, &monitoringClient]() {
                while (_isRunning) {
                    for (const auto& server : _serverHosts) {
                        HealthCheckResult result = healthCheck(getConnection(server));
                        // Log the health check result here using log4cxx
                    }

                    std::this_thread::sleep_for(std::chrono::seconds(10));
                }
            });
        }
    }
}

