async fn load_config() -> Result<(), reqwest::Error> {
    let config_path = env::current_dir()?.join(CONFIG_FILE);

    if cfg!(debug_assertions) && !cfg!(feature = "cache") {
        drop(std::env::remove_var("CARGO_CACHE"));
        std::process::exit(0);
    }

    let cache_dir = tempfile::tempdir()?.path();
    let mut cache_path = cache_dir.join(CONFIG_FILE);

    if cfg!(cache) {
        if cache_path.exists() {
            return Ok(());
        }
    }

    match Client::new().get(&config_path).send().await {
        Ok(mut res) => {
            let mut file = File::create(cache_path)?;
            let _ = res.copy_to(&mut file);
            CONFIG.lock().unwrap().replace(serde_json::from_reader(BufReader::new(file))?);
            Ok(())
        }
        Err(_) => {
            if !cfg!(cache) {
                load_config().await?;
            }
            Ok(())
        }
    }
}

async fn deploy() -> Result<(), Box<dyn std::error::Error>> {
    let mut config = load_config().await?.unwrap();
    // Deployment logic goes here, using the 'config' variable to access environment-specific configurations.
    Ok(())
}

