```cpp
#include <openssl/evp.h>
#include <openssl/sha.h>

EVP_CIPHER_CTX* initAES256CBCPad(const unsigned char *password, size_t passwordLength) {
    EVP_CIPHER_CTX* ctx = EVP_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();

    // Set IV length and key length
    unsigned char iv[AES_BLOCK_LENGTH] = {0};

    // Derive encryption key from password using SHA-256
    unsigned char key[EVP_MAX_KEY_LENGTH];
    SHA256(password, passwordLength, key);

    int res = EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
    if (res != 1) {
        EVP_CTX_free(ctx);
        return nullptr;
    }

    return ctx;
}

void cleanAES256CBCPad(EVP_CIPHER_CTX* ctx) {
    EVP_EncryptFinal_ex(ctx, nullptr, nullptr);
    EVP_CTX_free(ctx);
}
```

