private:
    // Base class for all cryptographic operations.
    struct CryptoOperation {
        virtual ~CryptoOperation() {}
        virtual std::unique_ptr<CryptoOperation> clone() = 0;
        virtual void encrypt(const std::string& password, std::vector<uint8_t>& data) = 0;
    };

    // Concrete implementation for AES-256-CBC.
    struct AES256CBCOperation : public CryptoOperation {
