        void encrypt(const std::string& password, std::vector<uint8_t>& data) override;
        EVP_CIPHER_CTX* ctx_;
    };

    // Helper function to initialize the AES cipher with a given password.
    static AES256CBCOperation* initAES(const std::string& password);

    // Map of registered cryptographic operations keyed by name.
