char* generateFilename(const char* path, const int maxLength) {
    // Generate unique filename using timestamp, UUID, and version identifier
    time_t now = time(NULL);
    char timestamp[16];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));

    char uuid[37];
    snprintf(uuid, sizeof(uuid), "%08x%04x%04x-%04x-%04x-%02x%02x-ibcd%02x%02x%02x%02x", (unsigned)rand(), (unsigned)(rand() >> 16), (unsigned)(rand() & 0xFFFF),
             (unsigned)(rand() >> 16), (unsigned)(rand() & 0xFFFF), (unsigned)(rand() & 0xFF), (unsigned)(rand() & 0xFF),
             (unsigned)(rand() & 0x3F), (unsigned)(rand() & 0x3F), (unsigned)(rand() & 0x3F), (unsigned)(rand() & 0x3F));

    char* versionIdentifier = getVersionIdentifier(); // Implement your custom function for version identifier

    size_t filenameLength = strlen(path) + strlen(timestamp) + strlen(uuid) + strlen(versionIdentifier) + 1; // Plus one for the separator
    if (filenameLength > maxLength) {
        fprintf(stderr, "Error: Filename exceeded maximum length of %d characters\n", maxLength);
        exit(EXIT_FAILURE);
    }

    char* filename = malloc(filenameLength + 1); // Allocate space for the filename and the null terminator
    strcpy(filename, path);
