        try {
            dataStore.processEvent(event);
        } catch (Exception e) {
            if (!retryPolicy.shouldRetry(e)) {
                // Handle dead-letter queues here
            } else {
                retryPolicy.backoff();
                processEvent(event);
            }
        }
    }
}

