        [HttpGet("{id}")]
        public async Task<IActionResult> GetConfiguration(int id)
        {
            var configJson = await externalAPIsService.FetchConfig(id);
            if (configJson == null) return NotFound();

            var configXml = XDocument.Parse(configJson);
            await CacheConfigurationAsync(configXml, id);

            return Ok(configXml);
        }

        private async Task CacheConfigurationAsync(XDocument configXml, int id)
        {
            var cacheKey = $"configuration:{id}";
            await cache.StringSetAsync(cacheKey, JsonConvert.SerializeObject(configXml), new TimeSpan(0, 15, 0)); // Cache for 15 minutes
        }
    }
