2. Java Backend (using a custom Union-Find implementation):

```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class ConfigurationService {
    private final Map<Integer, DisjointSet> disjointSets = new ConcurrentHashMap<>();
    private final AtomicLong timestamp = new AtomicLong(0);

    public int[] findDisjointPairs(int[] array) {
        for (int i : array) {
            disjointSets.computeIfAbsent(i, x -> new DisjointSet(timestamp.getAndIncrement()));
        }
        return new UnionFind(disjointSets).findDisjointPairs(array);
    }

    static class DisjointSet {
        private final long root;

        public DisjointSet(long timestamp) {
            this.root = timestamp * (timestamp + 1) / 2 + id % timestamp;
        }

        public long findRoot() {
            return root;
        }

        public void union(DisjointSet other) {
            long thisRoot = findRoot();
            long otherRoot = other.findRoot();
            if (thisRoot < otherRoot) {
                other.root = thisRoot;
            } else {
                this.root = otherRoot;
            }
        }
    }

    static class UnionFind {
        private final Map<Long, DisjointSet> sets;

        public int findDisjointPairs(int[] array) {
            int pairs = 0;
            for (int i = 0; i < array.length - 1; ++i) {
                long set1 = sets.get(array[i]).findRoot();
                long set2 = sets.get(array[i + 1]).findRoot();
                if (set1 != set2) {
                    pairs++;
                    sets.get(set1).union(sets.get(set2));
                }
            }
            return pairs;
        }

        public UnionFind(Map<Integer, DisjointSet> disjointSets) {
            this.sets = new HashMap<>();
            for (Map.Entry<Integer, DisjointSet> entry : disjointSets.entrySet()) {
                this.sets.put(entry.getValue().findRoot(), entry.getValue());
            }
        }
    }
}
```']

