use std::process::{Command, Stdio};
use time::SystemTime;
use log::{debug, error};

fn measure_and_log_compile(binary_name: &str) {
    let start = SystemTime::now();
    let mut compile_command = Command::new("cargo");
    compile_command.arg("build");
    compile_command.stdin(Stdio::null());
    compile_command.stdout(Stdio::null());
    compile_command.stderr(Stdio::piped());

    let mut process = compile_command.spawn().expect("Failed to spawn cargo build command");
    let error_output = process.error_output().unwrap();
    let mut error = String::new();
    error_output.read_to_string(&mut error);

    if !error.is_empty() {
        error!("Compilation failed with error: {}", error);
        return;
    }

    process.wait().expect("Failed to execute cargo build command");

    let elapsed = start.elapsed().unwrap().as_secs_f64();
    debug!("Compiled {} in {:.2} seconds", binary_name, elapsed);
}
