public class OutputSink implements SinkFunction<String> {
  private static final int MAX_RETRIES = 3;
  private static final int RETRY_DELAY = 1000;
  private transient int retryCount = 0;

  @Override
  public void invoke(String value, Context context) throws Exception {
    if (!context.isOperatorRegistered()) {
      // Operator is not yet registered (initialization phase or failure recovery).
      // Register the sink operator before processing data to ensure reliable delivery.
    }

    // Attempt to process the message, with retries and backpressure handling.
    if (!process(value)) {
      context.timerService().registerEventTimeTimer(context.timerService().currentProcessingTime() + RETRY_DELAY);
    }
  }

  private boolean process(String value) {
    // Process the message, with potential errors and backpressure handling.
    if (retryCount < MAX_RETRIES) {
