["1. Union-Find Data Structure (using Disjoint Set Data structure):

```javascript
class UnionFind {
  constructor(size) {
    this.ids = Array(size).fill(null).map((_, i) => i);
    this.count = size;
  }

  find(x) {
    if (this.ids[x] !== x) this.ids[x] = this.find(this.ids[x]);
    return this.ids[x];
  }

  union(x, y) {
    const rootX = this.find(x);
    const rootY = this.find(y);

    if (rootX === rootY) return;

    if (this.count[rootX] < this.count[rootY]) [rootX, rootY] = [rootY, rootX];

    this.ids[rootY] = rootX;
    this.count[rootX] += this.count[rootY];
  }
}
```

