        const timestamp = moment().format('YYYYMMDD_HHmmss');
        const randomValue = this.randomValueGenerator.generateInclusive(0, 9999);
        const uniqueFilename = `${timestamp}_${randomValue}${versionIdentifier}`;
        return uniqueFilename.substring(0, 255); // Ensure filename length does not exceed 255 characters
    }
}
