void retry(const std::function<void()>& function, uint32_t maxRetries = 10) {
    for (uint32_t i = 0; i < maxRetries; ++i) {
        try {
            function();
            return; // Operation was successful.
        } catch (const std::exception& e) {
            if (i >= maxRetries - 1) {
                throw e; // Maximum retries reached, rethrow the exception.
