namespace bp = boost::pool;
using IoTDataPoint = std::tuple<int64_t, int, double>; // Timestamp, Device ID, Measurement Value
using StorageResponse = std::pair<int, std::string>; // Status Code, Response Message
using ApiCallResult = std::pair<StorageResponse, boost::system::error_code>;

// Token Bucket Algorithm for rate limiting and backpressure
class RateLimiter {
public:
    explicit RateLimiter(double tokenRate, double burstSize) : _tokenRate(tokenRate), _burstSize(burstSize) {}

    bool getToken() {
        std::unique_lock<std::mutex> lock(_tokensMutex);
        _cv.wait_until(lock, std::chrono::steady_clock::now() + std::chrono::milliseconds(1), [this]() { return _tokens > 0 || _tokens + _burstSize >= _tokenRate; });
        if (_tokens < _tokens + _burstSize) {
            _tokens += _burstSize;
            _tokensLeft -= _burstSize;
        }
        return true;
    }

    void addTokens(double additionalTokens) {
        std::unique_lock<std::mutex> lock(_tokensMutex);
        _tokens += additionalTokens;
        _tokensLeft += additionalTokens;
    }

private:
    double _tokenRate, _burstSize, _tokens = 0, _tokensLeft = _tokenRate * 1000; // tokens per millisecond
    std::mutex _tokensMutex;
    std::condition_variable _cv;
};

// Thread-safe data structure for managing incoming data points
class DataQueue {
public:
    explicit DataQueue(size_t capacity) : _queue(capacity) {}

    void enqueue(const IoTDataPoint& dataPoint) {
        std::unique_lock<std::mutex> lock(_mutex);
        _queue.push(dataPoint);
        _cv.notify_one();
    }

    bool dequeue(IoTDataPoint& dataPoint, std::chrono::milliseconds timeout = std::chrono::milliseconds(0)) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto result = _cv.wait_for(lock, timeout, [this]() { return !_queue.empty(); });
        if (result == std::cv_status::no_timeout && _queue.empty()) return false;
        dataPoint = _queue.front();
        _queue.pop();
        return true;
    }

private:
    std::queue<IoTDataPoint> _queue;
    std::mutex _mutex;
    std::condition_variable _cv;
};

// Connection pool for API requests
class ApiConnectionPool {
public:
    explicit ApiConnectionPool(size_t maxConnections) : _connections(), _maxConnections(maxConnections) {}

    boost::asio::ip::tcp::socket acquire() {
        std::unique_lock<std::mutex> lock(_mutex);
        if (_idleConnections.empty()) {
            if (_openConnections < _maxConnections) {
                _openConnections++;
                return boost::asio::ip::tcp::socket(IO_SERVICE);
            } else {
                auto it = std::find_if(_idleConnections.rbegin(), _idleConnections.rend(), [&](const auto& socket) {
                    return !socket.second.connected();
                });
                if (it != _idleConnections.rend()) {
                    _idleConnections.erase(it);
                    return std::move(*it).first;
                } else {
                    throw std::runtime_error("No idle or open connections available.");
                }
            }
        } else {
            auto socket = std::move(_idleConnections.back().first);
            _idleConnections.pop_back();
            return socket;
        }
    }

    void release(boost::asio::ip::tcp::socket&& socket) {
        std::unique_lock<std::mutex> lock(_mutex);
        if (socket.is_open()) {
            _openConnections--;
            socket.lowest_layer().close();
        } else {
            _idleConnections.emplace_back(std::move(socket), false);
        }
    }

private:
    boost::asio::io_service IO_SERVICE;
    std::deque<std::pair<boost::asio::ip::tcp::socket, bool>> _idleConnections;
    std::deque<boost::asio::ip::tcp::socket> _openConnections;
    const size_t _maxConnections;
    std::mutex _mutex;
};

