namespace FieldUpdaterLibrary
{
    public class FieldUpdater
    {
        private readonly Dictionary<string, XmlDocument> _documents = new Dictionary<string, XmlDocument>();
        private readonly HttpClient _httpClient;

        public FieldUpdater(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public void UpdateFields(string resourceId, List<string> fieldNames, List<string> xmlDocumentsPaths)
        {
            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            Parallel.ForEach(xmlDocumentsPaths, options, path => UpdateFieldsAsync(resourceId, fieldNames, path));
        }

        private async Task UpdateFieldsAsync(string resourceId, List<string> fieldNames, string xmlDocumentPath)
        {
            try
            {
                var xmlDocument = LoadXmlDocument(xmlDocumentPath);

                if (!_documents.TryAdd(xmlDocumentPath, xmlDocument))
                    xmlDocument = _documents[xmlDocumentPath];

                foreach (var fieldName in fieldNames)
                {
                    var nodes = FindNodesByXPath(xmlDocument, $"//{fieldName}");

                    if (nodes.Count > 1 && !ShouldContinueOnError)
                        throw new AmbiguousElementException($"More than one element with name '{fieldName}' found in document '{xmlDocumentPath}'.");

                    var dialogField = FindDialogField(resourceId, fieldName);

                    if (dialogField == null)
                        continue;

                    var updatedValue = nodes.FirstOrDefault()?.Value ?? string.Empty;

                    if (!string.IsNullOrEmpty(updatedValue))
                        dialogField.UpdateValue(updatedValue);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error updating fields in document '{xmlDocumentPath}': {ex.Message}");
            }
        }

        private XmlDocument LoadXmlDocument(string xmlDocumentPath)
        {
            try
            {
                return XDocument.Load(xmlDocumentPath).CreateNavigator().QueryExpr() as XmlDocument;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error loading XML document '{xmlDocumentPath}': {ex.Message}");
                throw;
            }
        }

        private IEnumerable<XPathNavigator> FindNodesByXPath(XmlDocument xmlDocument, string xpath)
        {
            try
            {
                return xmlDocument.SelectNodes(xpath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error finding nodes by XPath '{xpath}': {ex.Message}");
                throw;
            }
        }

        private IDialogField FindDialogField(string resourceId, string fieldName)
        {
            // Implement your own logic to find the dialog field based on resourceId and fieldName
            // This is just a placeholder for your implementation.
            return null;
        }
    }
}
