Here's a sample code snippet using Java and Netty for handling concurrent OAuth token requests:

```java
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.SimpleChannelInboundHandler;
import java.security.*;
import java.util.concurrent.*;

public class TokenHandler extends SimpleChannelInboundHandler<OAuthRequest> {
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    // ... Other fields and methods defining authentication, KMS integration, etc.

    @Override
    protected void channelRead0(final ChannelHandlerContext ctx, OAuthRequest request) throws Exception {
        Future<OAuthResponse> future = executor.submit(() -> handleRequest(request));
        ctx.writeAndFlush(future);
    }

    private OAuthResponse handleRequest(OAuthRequest request) throws Exception {
        // Authenticate the user
        User user = authenticate(request.getHeaders());

        // Retrieve keys from KMS
        KeyStore keyStore = kmsClient.retrieveKeys(user);

        // Construct PKCS#12 file and encode as base64
        PKCS12KeyStore pkcs12KeyStore = new PKCS12KeyStore(keyStore);
        byte[] pkcs12Bytes = pkcs12KeyStore.getCertificateChain("alias").encode();

        return OAuthResponse.builder()
                .statusCode(HttpStatus.OK)
                .contentType("application/x-pkcs12")
                .body(Base64.getEncoder().encodeToString(pkcs12Bytes))
                .build();
    }
}
```']

