void HighThroughputQueue::Run() {
    _kafka_consumer.Subscribe("transaction-topic");

    _executor.SetMaxThreads(_concurrency_level);

    while (true) {
        absl::StatusOr<std::vector<TransactionEvent>> events = _kafka_consumer.Poll(boost::system_time::steady_clock::now() + boost::posix_time::milliseconds(_config.timeout_ms));
        if (!events.ok()) {
