        } else {
            std::lock_guard<std::mutex> lock(_queue_mutex);
            _queue.insert(_queue.end(), events.value().begin(), events.value().end());
            _queue_cv.notify_one();
        }
    }
}

void Worker(HighThroughputQueue& queue) {
    while (true) {
        std::unique_lock<std::mutex> lock(_queue_mutex);
        _queue_cv.wait(lock, [&queue]() -> bool { return !queue._queue.empty(); });

        auto event = queue._queue.front();
        queue._queue.pop_front();

