```rust
use std::collections::{HashMap, VecDeque};
use std::fmt;
use std::rc::Rc;
use std::sync::Arc;
use std::thread;

#[derive(Clone)]
struct Stage {
    process: Box<dyn FnMut(&Vec<u8>) -> Vec<u8>>,
}

impl fmt::Debug for Stage {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Stage")
    }
}

struct Pipeline {
    stages: VecDeque<Rc<RefCell<Stage>>>,
}

impl Pipeline {
    fn new(stages: Vec<Box<dyn FnMut(&Vec<u8>) -> Vec<u8>>) -> Self {
        let mut pipeline = Self {
            stages: VecDeque::new(),
        };
        for stage in stages {
            pipeline.push_back(Rc::new(RefCell::new(Stage { process: stage })));
        }
        pipeline
    }

    fn push_back(&mut self, stage: Rc<RefCell<Stage>>) {
        self.stages.push_back(stage);
    }

    fn process(&self, data: Vec<u8>) -> Vec<u8> {
        let mut data = data;
        for stage in self.stages.iter() {
            *data = (stage.borrow_mut().process)(data);
        }
        data
    }
}

