        if (cancellationToken.IsCancellationRequested) {
            throw new OperationCanceledException();
        }

        var key = (min, max);
        if (_cache.TryRemove(key, out _)) {
            // Cache hit - return cached value and reset the expiration time
            _cache[key] = GenerateInternal(min, max);
            return _cache[key];
        }

        // Cache miss - generate a new random number and add it to the cache
