        def __init__(self, rate, burst):
            self.rate = rate
            self.burst = burst
            self.tokens = burst
            self.refill_interval = 1/rate

        def take(self):
            if self.tokens > 0:
                self.tokens -= 1
                return True
            elif time() - self.last_refill >= self.refill_interval:
                self.tokens = self.burst
                self.last_refill = time()
                return True
