    uint64_t UE_ID;
    uint32_t RNTI;
    uint64_t trafficLoad;
} RX_UE_REPORT;

typedef struct CRNC_INDICATION_REL8_TAG {
    bool indicator;
    double probability;
} CRNC_INDICATION_REL8_TAG;

// External UE information service function, subject to rate limits and latency
void requestUEInfo(uint64_t UE_ID, void (*callback)(RX_UE_INFORMATION_TAG*), double *rateLimit);

// Global variables for synchronization and resource management
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
double networkLoadFactor = 0.5;
int rateLimit = 100;
int maxConcurrentRequests = 10;
CRNC_INDICATION_REL8_TAG crncIndicationRel8Tag = {false, 0.3}; // Configurable probability model
RX_UE_INFORMATION_TAG ueInformationCache[MAX_UE_COUNT]; // Cache for UE information

// Process a stream of UE reports and integrate with the external UE information service
void processUEReports(queue<RX_UE_REPORT> *reportStream, int logLevel) {
    double rntiRequestRate = rateLimit / maxConcurrentRequests; // Calculate request rate per RNTI
    double currentTime, sleepTime;
    struct timeval startTime, endTime;

    while (!queue_empty(reportStream)) {
        gettimeofday(&startTime, NULL);
        currentTime = (startTime.tv_sec + startTime.tv_usec / 1000000.0);

        // Process the next report
        RX_UE_REPORT report = queue_pop(reportStream);
        uint64_t UE_ID = report.UE_ID;

        // Allocate RNTI based on network conditions and adaptive rate control
        uint32_t rnti;
        if (!ueInformationCache[UE_ID].RNTI || networkLoadFactor > 0.8) {
            rnti = allocateNewRNTI(UE_ID);
        } else {
            rnti = ueInformationCache[UE_ID].RNTI;
        }

        // Set CRC indication based on configurable probability model
        CRNC_INDICATION_REL8_TAG *indicationTag = &crncIndicationRel8Tag;
        if (indicationTag->probability > rand() / RAND_MAX) {
            indicationTag->indicator = true;
        } else {
            indicationTag->indicator = false;
        }

        // Request UE information from the external service
        requestUEInfo(UE_ID, createUEInformationCallback(rnti, indicationTag->indicator), &rntiRequestRate);

        // Monitor and log resource usage and performance metrics
        if (logLevel > 1) {
            gettimeofday(&endTime, NULL);
            sleepTime = (endTime.tv_sec + endTime.tv_usec / 1000000.0) - currentTime;
            printf("UE %lld processed in %.3f ms\n", UE_ID, sleepTime * 1000);
        }
    }
}
```

