char *safe_string_slice(const char *input, size_t limit) {
    if (strlen(input) > limit) return NULL;
    char *result = malloc(limit + 1); // +1 for the appended slash
    strncpy(result, input, limit);
    result[limit] = '/';
    result[limit+1] = '\0';
    return result;
}
