// Helper function for modifying filenames based on digit count
std::string modifyFileName(const std::string& originalFilename) {
    constexpr std::regex filenameRegex("\\.[^.]+$");
    constexpr std::regex numberRegex("\\d+");
    std::smatch match;
    if (std::regex_search(originalFilename, match, filenameRegex)) {
        std::string extension = match[0];
        std::string numberStr = "";
        if (std::regex_search(extension, match, numberRegex)) {
            numberStr = match[0];
            extension.erase(extension.find(numberStr));
        }

        int digitCount = numberStr.length();
        std::ostringstream oss;
        oss << digitCount + 1;
        numberStr = oss.str();

        return originalFilename.replace(originalFilename.end() - digitCount, originalFilename.end(), numberStr) + ".new." + extension;
    }
    return originalFilename;
}
