3. Java NIO Connection:
  - Establish a secure connection to a remote server using Java NIO channels and SSL/TLS.

```java
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import javax.net.ssl.*;

public class SecureConnection {
    private SocketChannel socketChannel;
    private SSLContext sslContext;

    public SecureConnection(String host, int port) throws Exception {
        // Initialize SSLContext and create SSLEngine
        sslContext = SSLContext.getInstance("TLS");
        TrustManager[] trustManagers = new TrustManager[]{new X509TrustManager() {
            @Override
            public void checkClientTrusted(X509Certificate[] x509Certificates, String s) {}

            @Override
            public void checkServerTrusted(X509Certificate[] x509Certificates, String s) {}
        }};
        sslContext.init(null, trustManagers, null);

        SSLSocketChannelFactory factory = SSLSocketChannelFactory.getDefault();
        factory.setSSLContext(sslContext);

        // Connect to server using SSLSocketChannel and handle connection state changes
        SSLSocketChannel sslChannel = (SSLSocketChannel) factory.createSocketChannel().connect(new InetSocketAddress(host, port));
        this.socketChannel = SocketChannel.open(sslChannel.getAsynchronousSocketChannel());
    }

    public void sendData(String data) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(data.getBytes());
        while (buffer.hasRemaining()) {
            socketChannel.write(buffer);
        }
    }

    public String receiveData() throws IOException, InterruptedException {
        ByteBuffer buffer = ByteBuffer.allocateDirect(1024);
        socketChannel.read(buffer);
        buffer.flip();
        byte[] bytes = new byte[buffer.remaining()];
        buffer.get(bytes);
        return new String(bytes);
    }

    public void closeConnection() throws IOException {
        this.socketChannel.close();
    }
}
```']

