import java.security.cert.X509Certificate;
import java.text.ParseException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CertificateService {
    private static final Logger LOGGER = LoggerFactory.getLogger(CertificateService.class);
    private AmazonS3 s3Client;
    private ConcurrentHashMap<String, byte[]> cache;

    public CertificateService(AmazonS3 s3Client) {
        this.s3Client = s3Client;
        this.cache = new ConcurrentHashMap<>();
        Security.addProvider(new BouncyCastleProvider());
    }

    public KeyPair generateCertFromRequest(HttpServletRequest request) throws AuthenticationException, IOException, NoSuchAlgorithmException, OperatorCreationException {
        ObjectMapper objectMapper = new ObjectMapper();
        JsonNode payload = objectMapper.readTree(request.getReader());
        String privateKeyPath = payload.get("private_key").asText();
        String certificatePath = payload.get("certificate").asText();

        byte[] privateKeyBytes = getResourceFromS3(privateKeyPath);
        byte[] certificateBytes = getResourceFromS3(certificatePath);

        // Process private key and certificate here

        return KeyPairGeneratorFactory.getInstance("RSA").generateKeyPair();
    }

    public X509Certificate deserializeCertFromByteArray(byte[] bytes) {
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        CertificateFactory cf = CertificateFactory.getInstance("X.509");
        return (X509Certificate) cf.generateCertificate(bis);
    }

    public PKCS10CertificationRequest deserializeCertReqFromByteArray(byte[] bytes) {
        ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
        PemReader reader = new PemReader(bis);
        PemObject pemObj = reader.readPemObject();
        if (pemObj == null || !(pemObj instanceof PemObject.CertificateRequest)) {
            throw new IllegalArgumentException("Invalid PKCS#10 certificate request");
        }
        return ((PemObject.CertificateRequest) pemObj).getCertificateRequest();
    }

    public byte[] getResourceFromS3(String key) {
        if (cache.containsKey(key)) {
            return cache.get(key);
        }
        GetObjectRequest request = new GetObjectRequest(System.getenv("S3_BUCKET"), key);
        S3Object s3Obj = s3Client.getObject(request);
        ByteArrayInputStream objectData = s3Obj.getObjectContent();
        byte[] resourceBytes;
        try {
            resourceBytes = IOUtils.toByteArray(objectData);
        } catch (IOException e) {
            LOGGER.error("Failed to fetch resource {}", key, e);
            throw new RuntimeException(e);
        }
        cache.putIfAbsent(key, resourceBytes);
        return resourceBytes;
    }
}
```

