class Service:
    def __init__(self):
        self.name = os.path.basename(__file__).split(".")[0]
        self.container = None
        self.image = f"{os.environ['CONTAINER_REGISTRY']}/{self.name}:latest"

    def init(self, client, log_level="INFO"):
        # Start container if not already running and configure logging within the container
        if not self.container:
            config = {
                "environment": {k: v for k, v in os.environ.items()},
                "log_opts": {"level": log_level}
            }
            self.container = client.containers.run(
