const crypto = require('crypto');
const fs = require('fs');

function getCertificate(oauthRequest) {
  // Fetch private key and certificate from specified location
  const privateKey = fs.readFileSync('/path/to/private_key', 'utf8');
  const cert = fs.readFileSync('/path/to/certificate', 'utf8');

  // Generate a PEM-formatted certificate using the private key and the certificate
  const pemCert = crypto.createCertificate({
    key: crypto.createPrivateKey(privateKey),
    cert: crypto.createCertificate(cert)
  });

  return pemCert;
}
