template <typename T> class CustomAllocator : public std::allocator<T> {
public:
    using value_type = T;
    using pointer = typename std::allocator<T>::pointer;
    using reference = typename std::allocator<T>::reference;
    using propagate_const_reference_t = typename std::allocator<T>::propagate_const_reference_t;
    using propagate_copy_construction_t = typename std::allocator<T>::propagate_copy_construction_t;

    CustomAllocator(MemoryPool& pool) : memory_pool_(pool) {}

    pointer allocate(size_type n, const void* hint = nullptr) {
        return memory_pool_.allocate(n);
    }

    void deallocate(pointer p, size_t n) noexcept {
        memory_pool_.deallocate(p, n);
    }

    template<class U>
    propagate_const_reference_t rebind() const noexcept {
        return CustomAllocator<U>(memory_pool_);
    }

    template<class U>
    propagate_copy_construction_t move() const noexcept {
        return CustomAllocator<U>(memory_pool_);
    }
private:
    MemoryPool& memory_pool_;
};

